Object.assign(SNIP,{});PRESET_NOTES["l48"]={"Ví dụ: Cái túi 0/1 với bảng hai chiều": "Đáp án 9: lấy món nặng 3 (giá trị 4) và món nặng 4 (giá trị 5). Tham lam theo giá trị/kg lấy món nặng 5 (tỉ số 1.4) trước, rồi chỉ còn chỗ cho món nặng 1: giá trị 8, kém hơn.", "Ví dụ: Một mảng, sức chứa giảm dần": "Cùng đáp án 9 với bộ nhớ O(W). Khi tính dp[c], ô dp[c − w[i]] nằm bên trái và chưa bị cập nhật ở lượt món i, nên vẫn là giá trị “chưa có món i”.", "Ví dụ: Tổng tập con": "Có tập con tổng 9: {4, 5}. Đây là cái túi mà giá trị chỉ là đúng/sai.", "Ví dụ: Cái túi không giới hạn số lượng": "Mỗi loại có vô hạn món. Đáp án 15: ba món nặng 3 (3 · 5), hoặc các món nặng 2, 3, 4 (3 + 5 + 7).", "Lỗi: duyệt sức chứa tăng dần trong cái túi 0/1": "In 6 thay vì 4: khi c = 4, ô dp[2] đã chứa món nặng 2, nên món này bị lấy lần thứ hai. Mỗi món chỉ có một cái thì đáp án đúng là 4 (lấy món nặng 3). Chiều vòng lặp quyết định món được dùng một hay nhiều lần."};EX_HINTS["l48"]=[["dp[c]: giá trị lớn nhất với sức chứa c, chỉ xét các món đã duyệt. Ban đầu toàn 0.", "Mỗi món i: cho c chạy từ W xuống w[i], dp[c] = max(dp[c], dp[c − w[i]] + v[i]). Chạy giảm dần để món i không bị lấy hai lần.", "Thử mọi tập con là 2^n: với n = 50 đã quá chậm. Tổng giá trị tới 10^11: long long."], ["Một bạn nhận tập túi có tổng s, bạn kia S − s. Chênh lệch |S − 2s|, nhỏ nhất khi s gần S/2 nhất.", "Chỉ cần xét s ≤ S/2: co[s] là bài tổng tập con, s chạy giảm dần cho mỗi túi.", "Tìm s ≤ S/2 lớn nhất có co[s] đúng; đáp án S − 2s."], ["W tới 10^9 nên không lập bảng theo sức chứa được. Tổng giá trị tối đa 100 · 1000 = 10^5: lập bảng theo giá trị.", "nhe[s]: khối lượng nhỏ nhất để có đúng tổng giá trị s. nhe[0] = 0, còn lại INF. Mỗi món: s giảm dần, nhe[s] = min(nhe[s], nhe[s − v] + w).", "Đáp án: s lớn nhất có nhe[s] ≤ W. Khối lượng cộng dồn có thể vượt int: long long."]];
/* ===================== BÀI 48 · Bài toán cái túi ===================== */
/* Bài 48 · Bài toán cái túi
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR48=[{label:"Ví dụ: Cái túi 0/1 với bảng hai chiều",input:"",code:"#include <iostream>\nusing namespace std;\n\nint dp[5][8];                          // hàng 0 toàn 0\n\nint main() {\n    int w[5] = {0, 1, 3, 4, 5};        // món 1..4 (bỏ ô 0 cho khớp chỉ số hàng)\n    int v[5] = {0, 1, 4, 5, 7};\n    int n = 4, W = 7;\n    for (int i = 1; i <= n; i++)\n        for (int c = 0; c <= W; c++) {\n            dp[i][c] = dp[i - 1][c];                               // không lấy món i\n            if (w[i] <= c) dp[i][c] = max(dp[i][c], dp[i - 1][c - w[i]] + v[i]);   // lấy món i\n        }\n    cout << dp[n][W] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","c"]}],py:{code:"w = [0, 1, 3, 4, 5]                    # món 1..4 (bỏ ô 0 cho khớp chỉ số hàng)\nv = [0, 1, 4, 5, 7]\nn, W = 4, 7\ndp = [[0] * (W + 1) for _ in range(n + 1)]   # hàng 0 toàn 0\nfor i in range(1, n + 1):\n    for c in range(W + 1):\n        dp[i][c] = dp[i - 1][c]                        # không lấy món i\n        if w[i] <= c:\n            dp[i][c] = max(dp[i][c], dp[i - 1][c - w[i]] + v[i])   # lấy món i\nprint(dp[n][W])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] w = { 0, 1, 3, 4, 5 };           // món 1..4 (bỏ ô 0 cho khớp chỉ số hàng)\n        int[] v = { 0, 1, 4, 5, 7 };\n        int n = 4, W = 7;\n        int[][] dp = new int[n + 1][];         // hàng 0 toàn 0\n        for (int i = 0; i <= n; i++) dp[i] = new int[W + 1];\n        for (int i = 1; i <= n; i++)\n            for (int c = 0; c <= W; c++)\n            {\n                dp[i][c] = dp[i - 1][c];                               // không lấy món i\n                if (w[i] <= c) dp[i][c] = Math.Max(dp[i][c], dp[i - 1][c - w[i]] + v[i]);   // lấy món i\n            }\n        Console.WriteLine(dp[n][W]);\n    }\n}"}},{label:"Ví dụ: Một mảng, sức chứa giảm dần",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int w[4] = {1, 3, 4, 5};\n    int v[4] = {1, 4, 5, 7};\n    int W = 7;\n    int dp[8] = {0};                   // dp[c]: giá trị lớn nhất với sức chứa c\n    for (int i = 0; i < 4; i++)\n        for (int c = W; c >= w[i]; c--)                 // GIẢM dần: mỗi món dùng một lần\n            dp[c] = max(dp[c], dp[c - w[i]] + v[i]);\n    cout << dp[W] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["c"]}],py:{code:"w = [1, 3, 4, 5]\nv = [1, 4, 5, 7]\nW = 7\ndp = [0] * (W + 1)                     # dp[c]: giá trị lớn nhất với sức chứa c\nfor i in range(4):\n    for c in range(W, w[i] - 1, -1):   # GIẢM dần: mỗi món dùng một lần\n        dp[c] = max(dp[c], dp[c - w[i]] + v[i])\nprint(dp[W])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] w = { 1, 3, 4, 5 };\n        int[] v = { 1, 4, 5, 7 };\n        int W = 7;\n        int[] dp = new int[W + 1];             // dp[c]: giá trị lớn nhất với sức chứa c\n        for (int i = 0; i < 4; i++)\n            for (int c = W; c >= w[i]; c--)    // GIẢM dần: mỗi món dùng một lần\n                dp[c] = Math.Max(dp[c], dp[c - w[i]] + v[i]);\n        Console.WriteLine(dp[W]);\n    }\n}"}},{label:"Ví dụ: Tổng tập con",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5] = {3, 34, 4, 12, 5};\n    int S = 9;\n    bool co[10] = {true};              // co[0] = đúng: tập rỗng\n    for (int i = 0; i < 5; i++)\n        for (int s = S; s >= a[i]; s--)\n            if (co[s - a[i]]) co[s] = true;\n    cout << (co[S] ? \"co\" : \"khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"co",ptr:["s"]}],py:{code:"a = [3, 34, 4, 12, 5]\nS = 9\nco = [False] * (S + 1)\nco[0] = True                           # tập rỗng\nfor x in a:\n    for s in range(S, x - 1, -1):\n        if co[s - x]:\n            co[s] = True\nprint(\"co\" if co[S] else \"khong\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 34, 4, 12, 5 };\n        int S = 9;\n        bool[] co = new bool[S + 1];\n        co[0] = true;                          // tập rỗng\n        foreach (int x in a)\n            for (int s = S; s >= x; s--)\n                if (co[s - x]) co[s] = true;\n        Console.WriteLine(co[S] ? \"co\" : \"khong\");\n    }\n}"}},{label:"Ví dụ: Cái túi không giới hạn số lượng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int w[3] = {2, 3, 4};\n    int v[3] = {3, 5, 7};\n    int W = 9;\n    int dp[10] = {0};\n    for (int i = 0; i < 3; i++)\n        for (int c = w[i]; c <= W; c++)               // TĂNG dần: món i được lấy nhiều lần\n            dp[c] = max(dp[c], dp[c - w[i]] + v[i]);\n    cout << dp[W] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["c"]}],py:{code:"w = [2, 3, 4]\nv = [3, 5, 7]\nW = 9\ndp = [0] * (W + 1)\nfor i in range(3):\n    for c in range(w[i], W + 1):       # TĂNG dần: món i được lấy nhiều lần\n        dp[c] = max(dp[c], dp[c - w[i]] + v[i])\nprint(dp[W])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] w = { 2, 3, 4 };\n        int[] v = { 3, 5, 7 };\n        int W = 9;\n        int[] dp = new int[W + 1];\n        for (int i = 0; i < 3; i++)\n            for (int c = w[i]; c <= W; c++)    // TĂNG dần: món i được lấy nhiều lần\n                dp[c] = Math.Max(dp[c], dp[c - w[i]] + v[i]);\n        Console.WriteLine(dp[W]);\n    }\n}"}},{label:"Lỗi: duyệt sức chứa tăng dần trong cái túi 0/1",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int w[2] = {2, 3};\n    int v[2] = {3, 4};\n    int W = 4;\n    int dp[5] = {0};\n    for (int i = 0; i < 2; i++)\n        for (int c = w[i]; c <= W; c++)               // SAI cho 0/1: món i bị lấy nhiều lần\n            dp[c] = max(dp[c], dp[c - w[i]] + v[i]);\n    cout << dp[W] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["c"]}],py:{code:"w = [2, 3]\nv = [3, 4]\nW = 4\ndp = [0] * (W + 1)\nfor i in range(2):\n    for c in range(w[i], W + 1):       # SAI cho 0/1: món i bị lấy nhiều lần\n        dp[c] = max(dp[c], dp[c - w[i]] + v[i])\nprint(dp[W])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] w = { 2, 3 };\n        int[] v = { 3, 4 };\n        int W = 4;\n        int[] dp = new int[W + 1];\n        for (int i = 0; i < 2; i++)\n            for (int c = w[i]; c <= W; c++)    // SAI cho 0/1: món i bị lấy nhiều lần\n                dp[c] = Math.Max(dp[c], dp[c - w[i]] + v[i]);\n        Console.WriteLine(dp[W]);\n    }\n}"}}];
const sim48=makeSim2(document.getElementById("sim-l48"),{id:"s48",presets:PR48});
makeEx2(document.getElementById("ex-l48"),sim48,[{t:"Ba lô",d:"Đầu vào: n và W (1 ≤ n ≤ 100, 1 ≤ W ≤ 10^5); n dòng sau là wᵢ vᵢ (1 ≤ wᵢ ≤ W, 1 ≤ vᵢ ≤ 10^9). Mỗi món lấy tối đa một lần. Đầu ra: tổng giá trị lớn nhất với tổng khối lượng không vượt W.",tests:[{in:"4 7\n1 1\n3 4\n4 5\n5 7",out:"9"},{in:"3 8\n3 30\n4 50\n5 60",out:"90"},{in:"1 4\n5 10",out:"0"},{in:"3 2\n1 1000000000\n1 1000000000\n1 1000000000",out:"2000000000"},{in:"50 300\n36 324\n9 571\n35 310\n33 198\n28 170\n10 990\n7 505\n15 224\n33 570\n33 159\n31 223\n2 76\n28 66\n9 511\n11 974\n9 58\n36 299\n22 716\n22 98\n16 279\n17 664\n1 959\n37 921\n19 647\n9 361\n28 180\n13 412\n39 284\n2 376\n7 296\n37 299\n38 509\n8 798\n8 232\n10 338\n31 548\n21 801\n28 114\n1 801\n24 433\n27 908\n21 1\n38 936\n26 482\n28 620\n17 159\n24 198\n30 578\n15 849\n37 169",out:"14410"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, W;\n    cin >> n >> W;\n    vector<int> w(n);\n    vector<long long> v(n);\n    for (int i = 0; i < n; i++) cin >> w[i] >> v[i];\n    vector<long long> dp(W + 1, 0);    // dp[c]: giá trị lớn nhất với sức chứa c\n    // mỗi món: c chạy GIẢM dần từ W về w[i]\n    cout << dp[W] << \"\\n\";\n    return 0;\n}",py:{start:"n, W = map(int, input().split())\nmon = [tuple(map(int, input().split())) for _ in range(n)]   # (w, v)\ndp = [0] * (W + 1)             # dp[c]: giá trị lớn nhất với sức chứa c\n# mỗi món: c chạy GIẢM dần từ W về w\nprint(dp[W])",hints:["dp[c]: giá trị lớn nhất với sức chứa c, chỉ xét các món đã duyệt. Ban đầu toàn 0.","Mỗi món (w, v): cho c chạy từ W xuống w (range(W, w - 1, -1)), dp[c] = max(dp[c], dp[c − w] + v).","Thử mọi tập con là 2^n: với n = 50 đã quá chậm."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] nw = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int n = (int)nw[0];\n        long W = nw[1];\n        long[] w = new long[n], v = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            w[i] = t[0];\n            v[i] = t[1];\n        }\n        long[] dp = new long[W + 1];           // dp[c]: giá trị lớn nhất với sức chứa c\n        // mỗi món: c chạy GIẢM dần từ W về w[i]\n        Console.WriteLine(dp[W]);\n    }\n}",hints:["dp[c]: giá trị lớn nhất với sức chứa c, chỉ xét các món đã duyệt. Ban đầu toàn 0.","Mỗi món i: cho c chạy từ W xuống w[i], dp[c] = Math.Max(dp[c], dp[c − w[i]] + v[i]). Chạy giảm dần để món i không bị lấy hai lần.","Thử mọi tập con là 2^n: với n = 50 đã quá chậm. Tổng giá trị tới 10^11: long."]}},{t:"Chia kẹo công bằng",d:"Có n túi kẹo, túi i có aᵢ viên. Chia các túi (không mở túi) cho hai bạn sao cho chênh lệch số kẹo ít nhất. Đầu vào: n (1 ≤ n ≤ 100) và n số aᵢ (1 ≤ aᵢ ≤ 1000). Đầu ra: chênh lệch nhỏ nhất.",tests:[{in:"4\n1 6 11 5",out:"1"},{in:"5\n3 1 4 2 2",out:"0"},{in:"1\n10",out:"10"},{in:"2\n5 5",out:"0"},{in:"6\n1 2 4 8 16 32",out:"1"},{in:"40\n115 80 82 142 298 223 292 271 282 201 296 220 7 233 272 151 22 49 14 15 2 172 189 47 230 262 225 50 231 300 45 248 82 111 37 102 125 181 17 203",out:"0"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    int S = 0;\n    for (int i = 0; i < n; i++) { cin >> a[i]; S += a[i]; }\n    vector<bool> co(S / 2 + 1, false); // co[s]: có tập túi tổng đúng s\n    co[0] = true;\n    // tổng tập con; rồi tìm s <= S/2 lớn nhất có co[s]\n    cout << S << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))\nS = sum(a)\nco = [False] * (S // 2 + 1)    # co[s]: có tập túi tổng đúng s\nco[0] = True\n# tổng tập con; rồi tìm s <= S // 2 lớn nhất có co[s]\nprint(S)",hints:["Một bạn nhận tập túi có tổng s, bạn kia S − s. Chênh lệch |S − 2s|, nhỏ nhất khi s gần S/2 nhất.","Chỉ cần xét s ≤ S // 2: co[s] là bài tổng tập con, s chạy giảm dần cho mỗi túi.","Tìm s ≤ S // 2 lớn nhất có co[s] đúng; đáp án S − 2s."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int S = 0;\n        foreach (int x in a) S += x;\n        bool[] co = new bool[S / 2 + 1];       // co[s]: có tập túi tổng đúng s\n        co[0] = true;\n        // tổng tập con; rồi tìm s <= S/2 lớn nhất có co[s]\n        Console.WriteLine(S);\n    }\n}",hints:["Một bạn nhận tập túi có tổng s, bạn kia S − s. Chênh lệch |S − 2s|, nhỏ nhất khi s gần S/2 nhất.","Chỉ cần xét s ≤ S/2: co[s] là bài tổng tập con, s chạy giảm dần cho mỗi túi.","Tìm s ≤ S/2 lớn nhất có co[s] đúng; đáp án S − 2s."]}},{t:"Ba lô siêu lớn",d:"Như bài Ba lô, nhưng sức chứa rất lớn: n ≤ 100, W ≤ 10^9, wᵢ ≤ 10^9, và giá trị nhỏ: 1 ≤ vᵢ ≤ 1000. Đầu ra: tổng giá trị lớn nhất.",tests:[{in:"3 8\n3 30\n4 50\n5 60",out:"90"},{in:"1 999999999\n1000000000 10",out:"0"},{in:"1 1000000000\n1000000000 10",out:"10"},{in:"6 15\n6 5\n5 6\n6 4\n6 6\n3 5\n7 2",out:"17"},{in:"40 1500000000\n577948912 55\n38867148 35\n659900057 3\n804329556 41\n968285626 51\n715218305 55\n92459034 89\n247724421 60\n341809082 99\n133800566 84\n51689412 9\n206382252 17\n903370433 27\n996549998 75\n113731759 18\n255147400 34\n345566381 25\n880502705 17\n606914056 82\n452990510 100\n47907712 10\n605419840 76\n93298820 50\n881736025 65\n11817965 95\n298708650 81\n662252425 20\n891524806 16\n136295179 12\n103069438 98\n407254247 69\n829605482 65\n488768218 74\n727634890 43\n501742515 52\n709086917 39\n849298566 38\n515467350 25\n137050691 2\n706614132 59",out:"710"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    long long W;\n    cin >> n >> W;\n    vector<long long> w(n);\n    vector<int> v(n);\n    int V = 0;\n    for (int i = 0; i < n; i++) { cin >> w[i] >> v[i]; V += v[i]; }\n    const long long INF = 4e18;\n    vector<long long> nhe(V + 1, INF); // nhe[s]: khối lượng nhỏ nhất để đạt đúng tổng giá trị s\n    nhe[0] = 0;\n    // cái túi 0/1 trên trục giá trị; đáp án: s lớn nhất có nhe[s] <= W\n    cout << 0 << \"\\n\";\n    return 0;\n}",py:{start:"n, W = map(int, input().split())\nmon = [tuple(map(int, input().split())) for _ in range(n)]   # (w, v)\nV = sum(v for w, v in mon)\nINF = 10**19\nnhe = [INF] * (V + 1)          # nhe[s]: khối lượng nhỏ nhất để đạt đúng tổng giá trị s\nnhe[0] = 0\n# cái túi 0/1 trên trục giá trị; đáp án: s lớn nhất có nhe[s] <= W\nprint(0)",hints:["W tới 10^9 nên không lập bảng theo sức chứa được. Tổng giá trị tối đa 100 · 1000 = 10^5: lập bảng theo giá trị.","nhe[s]: khối lượng nhỏ nhất để có đúng tổng giá trị s. nhe[0] = 0, còn lại INF. Mỗi món: s giảm dần, nhe[s] = min(nhe[s], nhe[s − v] + w).","Đáp án: s lớn nhất có nhe[s] ≤ W."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] nw = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int n = (int)nw[0];\n        long W = nw[1];\n        long[] w = new long[n], v = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            w[i] = t[0];\n            v[i] = t[1];\n        }\n        int V = 0;\n        foreach (long x in v) V += (int)x;\n        const long INF = (long)4e18;\n        long[] nhe = new long[V + 1];          // nhe[s]: khối lượng nhỏ nhất để đạt đúng tổng giá trị s\n        for (int s = 1; s <= V; s++) nhe[s] = INF;\n        // cái túi 0/1 trên trục giá trị; đáp án: s lớn nhất có nhe[s] <= W\n        Console.WriteLine(0);\n    }\n}",hints:["W tới 10^9 nên không lập bảng theo sức chứa được. Tổng giá trị tối đa 100 · 1000 = 10^5: lập bảng theo giá trị.","nhe[s]: khối lượng nhỏ nhất để có đúng tổng giá trị s. nhe[0] = 0, còn lại INF. Mỗi món: s giảm dần, nhe[s] = min(nhe[s], nhe[s − v] + w).","Đáp án: s lớn nhất có nhe[s] ≤ W."]}}]);

